import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';
import {
  BarChart3, DollarSign, TrendingUp, Package,
  Filter, Download, RefreshCw, X
} from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

export default function Reports() {
  const { storeId, staff } = useAuth();
  const [tab, setTab] = useState('sales');
  const [dateRange, setDateRange] = useState('today');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Data
  const [salesData, setSalesData] = useState([]);
  const [profitData, setProfitData] = useState(null);
  const [inventoryData, setInventoryData] = useState(null);
  const [currencySymbol, setCurrencySymbol] = useState('K');

  const isAdminOrManager = staff?.role === 'admin' || staff?.role === 'manager';

  useEffect(() => {
    if (storeId) {
      supabase
        .from('company_settings')
        .select('currency_symbol')
        .eq('store_id', storeId)
        .single()
        .then(({ data }) => {
          if (data?.currency_symbol) setCurrencySymbol(data.currency_symbol);
        })
        .catch(() => {});
    }
  }, [storeId]);

  const getDateRange = () => {
    const now = new Date();
    let start = new Date();
    let end = new Date();
    switch (dateRange) {
      case 'today':
        start.setHours(0,0,0,0);
        end.setHours(23,59,59,999);
        break;
      case 'yesterday':
        start.setDate(now.getDate() - 1);
        start.setHours(0,0,0,0);
        end.setDate(now.getDate() - 1);
        end.setHours(23,59,59,999);
        break;
      case 'thisWeek':
        const day = now.getDay();
        start.setDate(now.getDate() - day);
        start.setHours(0,0,0,0);
        end.setHours(23,59,59,999);
        break;
      case 'thisMonth':
        start.setDate(1);
        start.setHours(0,0,0,0);
        end.setHours(23,59,59,999);
        break;
      case 'lastMonth':
        start.setMonth(now.getMonth() - 1, 1);
        start.setHours(0,0,0,0);
        end.setMonth(now.getMonth(), 0);
        end.setHours(23,59,59,999);
        break;
      case 'custom':
        if (startDate && endDate) {
          start = new Date(startDate);
          end = new Date(endDate);
          end.setHours(23,59,59,999);
        }
        break;
    }
    return { start: start.toISOString(), end: end.toISOString() };
  };

  const loadData = async () => {
    if (!storeId) return;
    setLoading(true);
    setError(null);
    try {
      const { start, end } = getDateRange();

      if (tab === 'sales') {
        const { data, error } = await supabase
          .from('sales')
          .select('*,customer:customers(name),staff:staff(full_name)')
          .eq('store_id', storeId)
          .eq('returned', false)
          .gte('created_at', start)
          .lte('created_at', end)
          .order('created_at', { ascending: false });
        if (error) throw error;
        setSalesData(data || []);
      } else if (tab === 'profit') {
        const { data: sales } = await supabase
          .from('sales')
          .select('total_amount')
          .eq('store_id', storeId)
          .eq('returned', false)
          .gte('created_at', start)
          .lte('created_at', end);
        const { data: items } = await supabase
          .from('sale_items')
          .select('quantity,cost_price')
          .gte('created_at', start)
          .lte('created_at', end);
        const totalRevenue = (sales || []).reduce((sum, s) => sum + s.total_amount, 0);
        const totalCost = (items || []).reduce((sum, i) => sum + (i.cost_price || 0) * i.quantity, 0);
        const grossProfit = totalRevenue - totalCost;
        const margin = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
        setProfitData({
          totalRevenue,
          totalCost,
          grossProfit,
          margin,
          transactionCount: (sales || []).length,
        });
      } else if (tab === 'inventory') {
        const { data: products } = await supabase
          .from('products')
          .select('name,stock_quantity,cost_price,unit_price')
          .eq('store_id', storeId)
          .eq('is_active', true);
        const items = (products || []).map(p => ({
          ...p,
          costValue: (p.cost_price || 0) * p.stock_quantity,
          retailValue: p.unit_price * p.stock_quantity,
        }));
        const totalCost = items.reduce((sum, i) => sum + i.costValue, 0);
        const totalRetail = items.reduce((sum, i) => sum + i.retailValue, 0);
        setInventoryData({
          totalCost,
          totalRetail,
          potentialProfit: totalRetail - totalCost,
          items,
        });
      }
    } catch (err) {
      setError(err.message);
      toast.error('Failed to load report data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (storeId) loadData();
  }, [storeId, tab, dateRange, startDate, endDate]);

  const formatCurrency = (value) => `${currencySymbol}${value.toFixed(2)}`;

  const chartData = [
    { day: 'Mon', sales: 1240 },
    { day: 'Tue', sales: 1890 },
    { day: 'Wed', sales: 980 },
    { day: 'Thu', sales: 2340 },
    { day: 'Fri', sales: 3120 },
    { day: 'Sat', sales: 2890 },
    { day: 'Sun', sales: 1560 },
  ];

  if (!isAdminOrManager) return <div className="p-8 text-red-600">Access Denied</div>;

  return (
    <div className="p-4 h-full overflow-y-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 mb-4">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <BarChart3 className="inline" /> Reports
        </h1>
        <button
          onClick={loadData}
          disabled={loading}
          className="px-3 py-1.5 bg-blue-600 text-white rounded flex items-center gap-1 text-sm w-full sm:w-auto"
        >
          <RefreshCw size={14} /> {loading ? 'Loading...' : 'Refresh'}
        </button>
      </div>

      {error && (
        <div className="mb-4 p-4 bg-red-50 text-red-700 rounded-lg flex items-center gap-2">
          <X className="text-red-600" /> {error}
        </div>
      )}

      {/* Tabs */}
      <div className="flex flex-wrap gap-2 mb-4 border-b pb-2">
        {['sales','profit','inventory'].map(t => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={`px-4 py-2 rounded-lg capitalize font-medium text-sm ${
              tab === t ? 'bg-green-600 text-white' : 'bg-gray-100 text-gray-700'
            }`}
          >
            {t}
          </button>
        ))}
      </div>

      {/* Date Filters */}
      <div className="flex flex-wrap items-end gap-3 mb-6 bg-white p-4 rounded-xl shadow">
        <div>
          <label className="block text-sm mb-1">Date Range</label>
          <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="p-2 border rounded text-sm">
            <option value="today">Today</option>
            <option value="yesterday">Yesterday</option>
            <option value="thisWeek">This Week</option>
            <option value="thisMonth">This Month</option>
            <option value="lastMonth">Last Month</option>
            <option value="custom">Custom</option>
          </select>
        </div>
        {dateRange === 'custom' && (
          <>
            <div>
              <label className="block text-sm mb-1">Start</label>
              <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="p-2 border rounded text-sm" />
            </div>
            <div>
              <label className="block text-sm mb-1">End</label>
              <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="p-2 border rounded text-sm" />
            </div>
          </>
        )}
        <button onClick={loadData} disabled={loading} className="px-4 py-2 bg-green-600 text-white rounded flex items-center gap-2 text-sm">
          <Filter size={16} /> Apply
        </button>
        {tab === 'sales' && salesData.length > 0 && (
          <button
            onClick={() => {
              const csv = [['Invoice','Date','Customer','Cashier','Payment','Total'].join(',')].concat(
                salesData.map(s => [
                  s.invoice_number,
                  new Date(s.created_at).toLocaleString(),
                  s.customer?.name || 'Walk-in',
                  s.staff?.full_name || '',
                  s.payment_method,
                  s.total_amount,
                ].join(','))
              ).join('\n');
              const blob = new Blob([csv], { type: 'text/csv' });
              const a = document.createElement('a');
              a.href = URL.createObjectURL(blob);
              a.download = `sales_report_${dateRange}.csv`;
              a.click();
            }}
            className="px-4 py-2 bg-blue-600 text-white rounded flex items-center gap-2 text-sm"
          >
            <Download size={16} /> CSV
          </button>
        )}
      </div>

      {/* Content area */}
      <div className="space-y-6">
        {/* Sales Tab */}
        {tab === 'sales' && (
          <>
            {/* Summary cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Total Sales</p>
                <p className="text-2xl font-bold text-green-600">
                  {formatCurrency(salesData.reduce((sum, s) => sum + s.total_amount, 0))}
                </p>
              </div>
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Transactions</p>
                <p className="text-2xl font-bold">{salesData.length}</p>
              </div>
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Avg Sale</p>
                <p className="text-2xl font-bold">
                  {formatCurrency(salesData.length > 0 ? salesData.reduce((s,c)=>s+c.total_amount,0)/ salesData.length : 0)}
                </p>
              </div>
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Cash Payments</p>
                <p className="text-2xl font-bold">
                  {formatCurrency(salesData.filter(s=>s.payment_method==='cash').reduce((sum,s)=>sum+s.total_amount,0))}
                </p>
              </div>
            </div>

            {/* Sales table: desktop + mobile */}
            <div className="bg-white rounded-xl shadow overflow-hidden">
              {/* Desktop table */}
              <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 border-b">
                    <tr>
                      <th className="p-3 text-left">Invoice</th>
                      <th className="p-3 text-left">Date</th>
                      <th className="p-3 text-left">Customer</th>
                      <th className="p-3 text-left">Cashier</th>
                      <th className="p-3 text-left">Payment</th>
                      <th className="p-3 text-right">Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {salesData.map(s => (
                      <tr key={s.id} className="border-t">
                        <td className="p-3">{s.invoice_number}</td>
                        <td className="p-3">{new Date(s.created_at).toLocaleString()}</td>
                        <td className="p-3">{s.customer?.name || 'Walk-in'}</td>
                        <td className="p-3">{s.staff?.full_name || ''}</td>
                        <td className="p-3">{s.payment_method}</td>
                        <td className="p-3 text-right font-medium">{formatCurrency(s.total_amount)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {/* Mobile cards */}
              <div className="md:hidden space-y-2 p-2">
                {salesData.map(s => (
                  <div key={s.id} className="bg-gray-50 p-3 rounded-lg">
                    <div className="flex justify-between">
                      <span className="font-bold">#{s.invoice_number}</span>
                      <span className="font-bold text-green-600">{formatCurrency(s.total_amount)}</span>
                    </div>
                    <div className="text-xs text-gray-500 mt-1">
                      {new Date(s.created_at).toLocaleString()} · {s.customer?.name || 'Walk-in'} · {s.staff?.full_name}
                    </div>
                    <span className="text-xs px-2 py-0.5 bg-gray-200 rounded-full mt-1 inline-block">{s.payment_method}</span>
                  </div>
                ))}
              </div>
            </div>
          </>
        )}

        {/* Profit Tab */}
        {tab === 'profit' && profitData && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-white p-4 rounded-xl shadow">
              <p className="text-sm text-gray-500">Revenue</p>
              <p className="text-2xl font-bold">{formatCurrency(profitData.totalRevenue)}</p>
            </div>
            <div className="bg-white p-4 rounded-xl shadow">
              <p className="text-sm text-gray-500">Cost</p>
              <p className="text-2xl font-bold">{formatCurrency(profitData.totalCost)}</p>
            </div>
            <div className="bg-white p-4 rounded-xl shadow">
              <p className="text-sm text-gray-500">Profit</p>
              <p className="text-2xl font-bold text-green-600">{formatCurrency(profitData.grossProfit)}</p>
            </div>
            <div className="bg-white p-4 rounded-xl shadow">
              <p className="text-sm text-gray-500">Margin</p>
              <p className="text-2xl font-bold">{profitData.margin.toFixed(1)}%</p>
            </div>
          </div>
        )}

        {/* Inventory Tab */}
        {tab === 'inventory' && inventoryData && (
          <>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Cost Value</p>
                <p className="text-2xl font-bold">{formatCurrency(inventoryData.totalCost)}</p>
              </div>
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Retail Value</p>
                <p className="text-2xl font-bold">{formatCurrency(inventoryData.totalRetail)}</p>
              </div>
              <div className="bg-white p-4 rounded-xl shadow">
                <p className="text-sm text-gray-500">Potential Profit</p>
                <p className="text-2xl font-bold text-green-600">{formatCurrency(inventoryData.potentialProfit)}</p>
              </div>
            </div>
            <div className="bg-white rounded-xl shadow overflow-hidden">
              <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 border-b">
                    <tr>
                      <th className="p-3 text-left">Product</th>
                      <th className="p-3 text-right">Stock</th>
                      <th className="p-3 text-right">Cost/Unit</th>
                      <th className="p-3 text-right">Price/Unit</th>
                      <th className="p-3 text-right">Cost Value</th>
                      <th className="p-3 text-right">Retail Value</th>
                    </tr>
                  </thead>
                  <tbody>
                    {inventoryData.items.map((item, idx) => (
                      <tr key={idx} className="border-t">
                        <td className="p-3">{item.name}</td>
                        <td className="p-3 text-right">{item.stock_quantity}</td>
                        <td className="p-3 text-right">{formatCurrency(item.cost_price || 0)}</td>
                        <td className="p-3 text-right">{formatCurrency(item.unit_price)}</td>
                        <td className="p-3 text-right">{formatCurrency(item.costValue)}</td>
                        <td className="p-3 text-right">{formatCurrency(item.retailValue)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="md:hidden space-y-2 p-2">
                {inventoryData.items.map((item, idx) => (
                  <div key={idx} className="bg-gray-50 p-3 rounded-lg">
                    <div className="flex justify-between font-medium">
                      <span>{item.name}</span>
                      <span>{item.stock_quantity} in stock</span>
                    </div>
                    <div className="grid grid-cols-2 gap-2 mt-1 text-sm">
                      <div>Cost: {formatCurrency(item.cost_price||0)}</div>
                      <div>Price: {formatCurrency(item.unit_price)}</div>
                      <div>Cost Value: {formatCurrency(item.costValue)}</div>
                      <div>Retail Value: {formatCurrency(item.retailValue)}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </>
        )}
      </div>

      {/* Sales Trend Chart (always visible) */}
      <div className="bg-white rounded-xl shadow p-4 mt-6">
        <h2 className="text-lg font-semibold mb-4">Sales Trend (Last 7 Days)</h2>
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="day" />
            <YAxis />
            <Tooltip formatter={(value) => `${currencySymbol} ${value}`} />
            <Line type="monotone" dataKey="sales" stroke="#10b981" strokeWidth={3} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
